import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { kineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, AmbientLight, DirectionalLight, DoubleSide } = ctx.THREE;

  // Root group
  const root = new Group();

  // ---------- Backdrop ----------
  const backdropGeom = new PlaneGeometry(7, 5.5);
  const backdropMat = new MeshStandardNodeMaterial({
    color: mix(color('#0b0b10'), color('#13131a'), uv().y),
    side: DoubleSide,
    roughness: 0.8,
    metalness: 0,
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -1.5);
  root.add(backdrop);

  // ---------- Lights ----------
  const ambient = new AmbientLight('#ffffff', 0.6);
  root.add(ambient);
  const keyLight = new DirectionalLight('#ffffff', 1.2);
  keyLight.position.set(0, 1, 1);
  root.add(keyLight);
  const rimLight = new DirectionalLight('#ffffff', 0.8);
  rimLight.position.set(0, -1, -1);
  root.add(rimLight);

  // ---------- Text Content ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Helper to find text by role (hero, subhead, caption)
  const findItem = (role) => items.find((i) => i.role === role) ?? {};

  // Hero
  const heroItem = findItem('hero');
  const heroText = heroItem.text ?? 'TIME, MACHINED.';
  const heroWords = heroText.split(' ');
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  const wordZOffsets = [0.12, 0, -0.12];
  let cursorX = 0;
  heroWords.forEach((word, idx) => {
    const txt = ctx.fontAtlas.createText(word, {
      fontSize: 124,
      color: '#16161d',
      align: 'left',
      letterSpacingPx: -0.01 * 124,
    });
    // Approximate width using fontSize * 0.6 per character
    const approxWidth = word.length * 124 * 0.6;
    txt.position.set(cursorX + approxWidth / 2, 0, wordZOffsets[idx] ?? 0);
    cursorX += approxWidth + 0.05 * 124; // small spacing
    heroGroup.add(txt);
  });
  root.add(heroGroup);

  // Underline
  const underlineGeom = new PlaneGeometry(2.6, 0.045);
  const underlineMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.2,
    roughness: 0.5,
    metalness: 0,
    side: DoubleSide,
  });
  const underline = new Mesh(underlineGeom, underlineMat);
  underline.position.set(-1.3, -0.05, 0); // anchored left
  underline.scale.set(0, 1, 1);
  root.add(underline);

  // Subhead
  const subheadItem = findItem('subhead');
  const subheadText = subheadItem.text ?? 'Every calibre begins as a solid billet.';
  const subhead = ctx.fontAtlas.createText(subheadText, {
    fontSize: 40,
    color: '#16161d',
    align: 'center',
    letterSpacingPx: 0.02 * 40,
  });
  subhead.position.set(0, -0.65, 0);
  root.add(subhead);

  // Caption
  const captionItem = findItem('caption');
  const captionText = captionItem.text ?? 'NOVA ATELIER / CALIBRE PROGRAM';
  const caption = ctx.fontAtlas.createText(captionText, {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.12 * 18,
  });
  caption.position.set(0, 1.15, 0);
  root.add(caption);

  // ---------- Cinematic Primitives ----------
  const primitiveRefs = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((p) => {
      if (p.name === 'kinetic-text' && p.trigger === 'load') {
        const prim = ctx.primitives['kinetic-text'](root, {
          staggerMs: 60,
          riseUnits: 0.35,
        });
        primitiveRefs.push(prim);
      } else {
        const prim = ctx.primitives[p.name](root, p.params);
        primitiveRefs.push(prim);
      }
    });
  }

  // ---------- GSAP Animations ----------
  const timelines = [];

  // Underline animation after kinetic-text completes
  const underlineTL = gsap.timeline({ paused: true });
  underlineTL.to(underline.scale, {
    x: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    delay: 0.12,
  });
  timelines.push(underlineTL);

  // Hook into kinetic-text timeline if present
  const kineticPrim = primitiveRefs.find((r) => r && r.timeline);
  if (kineticPrim && kineticPrim.timeline) {
    kineticPrim.timeline.eventCallback('onComplete', () => {
      underlineTL.play();
    });
  } else {
    // fallback: start after short delay
    gsap.delayedCall(0.8, () => underlineTL.play());
  }

  // Store cleanup
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose geometries and materials
    backdropGeom.dispose();
    backdropMat.dispose();
    underlineGeom.dispose();
    underlineMat.dispose();

    // Cleanup primitives
    primitiveRefs.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });

    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());
  };

  return root;
}
